import{_ as p,r as a,o,c,e as n,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Site Manager - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Checking Site Configuration State","slug":"checking-site-configuration-state","link":"#checking-site-configuration-state","children":[]},{"level":2,"title":"Retrieving a Site","slug":"retrieving-a-site","link":"#retrieving-a-site","children":[]},{"level":2,"title":"Accessing Multiple Sites","slug":"accessing-multiple-sites","link":"#accessing-multiple-sites","children":[]},{"level":2,"title":"Site Context","slug":"site-context","link":"#site-context","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/services/site.md","filePath":"4.x/extend/services/site.md"}'),r={name:"4.x/extend/services/site.md"};function u(d,s,k,h,g,m){const e=a("pre-heading"),t=a("post-heading");return o(),c("div",null,[n(e),s[0]||(s[0]=i("h1",null,"Site Manager",-1)),n(t),s[1]||(s[1]=l(`<h3 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h3><p>The global <code>Site</code> facade is included with October CMS to provide tools for working with <a href="./../../cms/multisite/multisite.html">multisite implementations</a>. All optional multisite features are enabled or disabled using the configuration file <strong>config/multisite.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;features&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;cms_maintenance_setting&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">]</span>
</code></pre></div><p>The <code>hasFeature</code> is used to check if a specific multisite feature is enabled.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$useMultisite</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasFeature</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms_maintenance_setting&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="checking-site-configuration-state"><a href="#checking-site-configuration-state" class="header-anchor">#</a> Checking Site Configuration State</h2><p>Use the <code>hasAnySite</code> to check if any enabled site is available.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasAnySite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>hasMultiSite</code> will return true if multiple site definitions are available.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasMultiSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>hasSiteGroups</code> will return true if multiple site definitions are using grouped definitions.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasSiteGroups</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="retrieving-a-site"><a href="#retrieving-a-site" class="header-anchor">#</a> Retrieving a Site</h2><p>Requesting a site will return a <code>System\\Models\\SiteDefinition</code> instance, with available attributes loaded from the cache driver or database.</p><p>The <code>getPrimarySite</code> method returns the primary site definition, used as a fallback for every occasion.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$site</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getPrimarySite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The frontend theme has a selected site that is used when rendering CMS pages, the <code>getActiveSite</code> site will return this site.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$site</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getActiveSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Likewise, the admin panel can select a site and this can be retrieved using the <code>getEditSite</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$site</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getEditSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To look up a site by its unique ID, use the <code>getSiteFromId</code> with the identifier.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$siteFour</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getSiteFromId</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To look up a site using its locale code, use the <code>getSiteForLocale</code> passing it the desired locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$frenchSite</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getSiteForLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="accessing-multiple-sites"><a href="#accessing-multiple-sites" class="header-anchor">#</a> Accessing Multiple Sites</h2><p>If multiple sites are returned, it will be as a populated instance of the <code>October\\Rain\\Database\\Collection</code> object.</p><p>List all the sites, including disabled sites, with the <code>listSites</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listSites</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>List only enabled sites with the <code>listEnabled</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>List sites enabled in the admin panel using <code>listEditEnabled</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listEditEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="site-context"><a href="#site-context" class="header-anchor">#</a> Site Context</h2><p>A site context is used to determine the active site, and this will restrict lookups to that site automatically. In some cases a global state is used to allow access to data across all states.</p><p>Use the <code>withContext</code> to change the context to a different site, passing it the ID of the desired site.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withContext</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Models in site 2 are now available.</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Activating the global context is performed using the <code>withGlobalContext</code> and passing it a closure.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withGlobalContext</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// All models are available in here.</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>hasGlobalContext</code> method to check if the global state is currently activated.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$global</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasGlobalContext</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../cms/multisite/multisite.html">Multisite</a></li><li><a href="./../multisite/multisite.html">Multisite Trait</a></li></ul></div>`,42))])}const S=p(r,[["render",u]]);export{v as __pageData,S as default};
